# ---------------- CERT-F4: f4 ladder re-derived (l169b2_run.py 668-701) ------
pm4 = w_syn >= FLOOR
_om4 = out_rows & cord_of_dst & pm4
outmass4 = np.zeros(Nall)
np.add.at(outmass4, src_all[_om4], np.abs(vals_all[_om4]))
_cm4 = outmass4[dn_new_g]
