        assert len(np.intersect1d(cl, cr)) == 0, (J, g, "side overlap (STOP)")
        cells = np.concatenate([cl, cr])
        isL = np.zeros(len(cells), bool)
        isL[:len(cl)] = True
        GROUPS[(J, g)] = (cells, isL)
